"use client";
/* eslint-disable react-hooks/set-state-in-effect */
import { useCallback, useEffect, useMemo, useState } from "react";

export default function LiveVideoManager(){const[data,setData]=useState([]),[filter,setFilter]=useState("ALL"),[error,setError]=useState("");const load=useCallback(async()=>{const r=await fetch("/api/admin/live-video");const j=await r.json();if(!r.ok)throw new Error(j.error?.message||"Unable to load live videos.");setData(j.data.sessions)},[]);useEffect(()=>{load().catch(e=>setError(e.message))},[load]);const rows=useMemo(()=>filter==="ALL"?data:data.filter(x=>x.status===filter),[data,filter]);async function end(liveId){if(!confirm("End this live video for everyone?"))return;const r=await fetch("/api/admin/live-video",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({action:"END",liveId})});const j=await r.json();if(!r.ok){setError(j.error?.message||"Unable to end live video.");return}await load()}const active=data.filter(x=>x.status==="LIVE");return <div className="space-y-7"><div className="flex flex-wrap items-end justify-between gap-4"><div><h2 className="text-2xl font-bold">Live video operations</h2><p className="mt-1 text-sm text-[#71847f]">Monitor sessions, guests, reports, PK activity and income.</p></div><select className="rounded-xl border border-[#d9e5e2] bg-white px-4 py-2 text-sm" value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">All sessions</option><option value="LIVE">Live now</option><option value="ENDED">Ended</option></select></div>{error&&<p className="rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Live now",active.length],["Current viewers",active.reduce((n,x)=>n+x.viewerCount,0)],["Open reports",data.reduce((n,x)=>n+x.reports.length,0)],["Gift income",data.reduce((n,x)=>n+Number(x.giftIncome),0).toLocaleString()]].map(([label,value])=><div key={label} className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><p className="text-xs font-semibold text-[#71847f]">{label}</p><p className="mt-2 text-2xl font-bold">{value}</p></div>)}</div><div className="grid gap-4">{rows.map(row=><article key={row.id} className="rounded-2xl border border-[#dfe9e7] bg-white p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><div className="flex items-center gap-2"><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold ${row.status==="LIVE"?"bg-emerald-100 text-emerald-700":"bg-slate-100 text-slate-600"}`}>{row.status}</span>{row.hostAway&&<span className="rounded-full bg-amber-100 px-2.5 py-1 text-[10px] font-bold text-amber-700">HOST AWAY</span>}</div><h3 className="mt-3 text-lg font-bold">{row.title}</h3><p className="text-xs text-[#71847f]">{row.host.name} ({row.host.publicId}) · {row.id}</p></div>{row.status==="LIVE"&&<button onClick={()=>end(row.id)} className="rounded-xl border border-red-200 px-4 py-2 text-sm font-bold text-red-700">End live</button>}</div><div className="mt-4 grid gap-3 text-sm sm:grid-cols-3 xl:grid-cols-6">{[["Viewers",row.viewerCount],["Peak",row.peakViewers],["Likes",row.likes],["Income",row.giftIncome],["Guests",row.guests.length],["Reports",row.reports.length]].map(([k,v])=><div key={k} className="rounded-xl bg-[#f4f8f7] p-3"><p className="text-[10px] font-semibold uppercase text-[#71847f]">{k}</p><p className="mt-1 font-bold">{v}</p></div>)}</div>{row.pk&&<p className="mt-3 rounded-xl bg-violet-50 p-3 text-sm text-violet-700">PK {row.pk.status} with {row.pk.opponent.title} ({row.pk.opponent.publicId})</p>}{row.guests.length>0&&<p className="mt-3 text-xs text-[#526b67]">Guests: {row.guests.map(g=>`${g.user.name} · ${g.status}${g.slot?` · slot ${g.slot}`:""}`).join("; ")}</p>}{row.reports.length>0&&<div className="mt-3 rounded-xl bg-red-50 p-3 text-xs text-red-700">{row.reports.map(r=><p key={r.id}><b>{r.reason}</b> from {r.reporter.name}{r.details?` — ${r.details}`:""}</p>)}</div>}</article>)}{!rows.length&&<div className="rounded-2xl border border-[#dfe9e7] bg-white p-10 text-center text-sm text-[#71847f]">No live-video sessions match this filter.</div>}</div></div>}
